import React, { useState } from 'react';

export default function PalindromeChecker() {
  const [input, setInput] = useState('');
  const [isPalindrome, setIsPalindrome] = useState(null);

  const checkPalindrome = (text) => {
    const cleaned = text.toLowerCase().replace(/[^a-z0-9]/gi, '');
    const reversed = cleaned.split('').reverse().join('');
    return cleaned && cleaned === reversed;
  };

  const handleChange = (e) => {
    const value = e.target.value;
    setInput(value);
    setIsPalindrome(checkPalindrome(value));
  };

  return (
    <div className="d-flex justify-content-center align-items-center vh-100 bg-light">
      <div className="card p-4 shadow w-100" style={{ maxWidth: '400px' }}>
        <h2 className="text-center mb-3">Palindrome Checker</h2>
        <input
          type="text"
          className="form-control text-center"
          placeholder="Enter text"
          value={input}
          onChange={handleChange}
        />
        {input && (
          <p
            className={`mt-3 fw-bold text-center ${
              isPalindrome ? 'text-success' : 'text-danger'
            }`}
          >
            {isPalindrome ? 'Palindrome ✅' : 'Not a Palindrome ❌'}
          </p>
        )}
      </div>
    </div>
  );
}
